@return The encrypted data, the IV, and the key used for encryption.
*/
encryption_result encrypt_data(
    const std::vector<unsigned char>& key,
    const std::vector<unsigned char>& data
) {
    // Ensure the key is at least 32 bytes long for AES-256
    if (key.size() < 32) {
        throw std::invalid_argument("Key must be at least 32 bytes long for AES-256.");
    }

    // Use AES-256 for encryption
    const size_t key_length = 32; // 256 bits
    std::vector<unsigned char> aes_key(key.begin(), key.begin() + key_length);

    // Generate a random IV
    std::vector<unsigned char> iv(AES_BLOCK_SIZE);
    if (RAND_bytes(iv.data(), AES_BLOCK_SIZE) != 1) {
        throw std::runtime_error("Failed to generate random IV.");
    }

    // Pad the data
    std::vector<unsigned char> padded_data = pad_data(data);

    // Prepare the output buffer
    std::vector<unsigned char> encrypted_data(padded_data.size());

    // Set up the AES key structure
    AES_KEY encrypt_key;
    if (AES_set_encrypt_key(aes_key.data(), key_length * 8, &encrypt_key) != 0) {
        throw std::runtime_error("Failed to set AES encryption key.");
    }

    // Perform the encryption
    AES_cbc_encrypt(
        padded_data.data(),
        encrypted_data.data(),
        padded_data.size(),
        &encrypt_key,
        iv.data(),
        AES_ENCRYPT
    );

    // Return the result
    encryption_result result;
    result.encrypted_data = encrypted_data;
    result.iv = iv;
    result.key = aes_key;
